// Présentation publique du collectif, distincte des échanges privés.
let journalCollection='Tout';
const domaineJournal=[{title:'La Serre du Domaine',text:'Un café, des fleurs et des projets.',image:'terrasse-fleurie.webp',category:'Lieux',route:'terrasse'},{title:'La maison ouverte sur le jardin',text:'Deux containers en L et une terrasse.',image:'maison-l-bois-reference.webp',category:'Habiter',route:'domaine'},{title:'Le jardin nous rassemble',text:'Observer, cultiver et apprendre ensemble.',image:'jardin-photo.webp',category:'Rencontres',route:'jardin'},{title:'Travailler autrement',text:'Une table pour échanger et entreprendre.',image:'terrasse-fleurie.webp',category:'Rencontres',route:'terrasse'},{title:'Un refuge à votre rythme',text:'Les habitats et leurs ressources.',image:'tiny-house-solaire-eau.webp',category:'Habiter',route:'sejours'},{title:'Nos lieux de vie',text:'Découvrir les chemins et espaces communs.',image:'jardin-photo.webp',category:'Lieux',route:'ville'}];
async function shareTerrace(){const link=location.origin+'/index.html#terrasse';try{await navigator.clipboard.writeText(link);toast('Lien public de la terrasse copié.')}catch{modal('<h2>Faire découvrir la terrasse</h2><p>Copiez ce lien public :</p><input aria-label="Lien public de la terrasse" readonly value="'+esc(link)+'">')}}
views.communaute=function(){return `<section class="journal-profile"><div class="journal-avatar">${domainEmblem()}</div><div><div class="eyebrow">LE JOURNAL PUBLIC DU PROJET</div><h1>Le Cercle du Domaine.</h1><p>Habiter. Se rencontrer. Faire grandir ses projets.<br>Le jardin, les lieux communs et les rencontres à imaginer ensemble.</p><div class="journal-actions"><a class="btn" href="/cercle-demo/">Entrer dans l’application ↗</a><a class="btn light" href="/cercle-demo">Essayer le nouveau Cercle ↗</a><button class="textlink" onclick="shareTerrace()">Partager le Domaine ↗</button></div><small>Page de présentation du Domaine · aucune publication privée affichée ici.</small></div></section><section class="journal-announcement"><img src="assets/terrasse-fleurie.webp" alt="Concept de la terrasse résidentielle couverte et très fleurie"><div><div class="eyebrow">À LA UNE · LA SERRE DU DOMAINE</div><h2>Un lieu pour se retrouver.<br>Et faire naître des idées.</h2><p>Tables en métal, bancs, cafétéria et espace entrepreneurs sous une pergola végétale.</p><a href="#terrasse" class="btn light">Découvrir la terrasse ↗</a></div></section><div class="journal-collections" role="group" aria-label="Collections du journal">${['Tout','Lieux','Habiter','Rencontres'].map(c=>`<button aria-pressed="${journalCollection===c}" onclick="journalCollection='${c}';render()">${c}</button>`).join('')}</div><div class="journal-grid">${domaineJournal.filter(p=>journalCollection==='Tout'||p.category===journalCollection).map(p=>`<a href="#${p.route}" class="journal-tile"><img src="assets/${p.image}" loading="lazy" alt="${p.title} · visuel conceptuel"><div><span>${p.category}</span><h3>${p.title}</h3><p>${p.text}</p></div></a>`).join('')}</div><section class="journal-private"><div><div class="eyebrow">VOTRE RÉSEAU AU QUOTIDIEN</div><h2>Le fil visuel, les profils et les rencontres.</h2><p>Publier avec un visuel du projet, aimer, commenter, enregistrer, compléter son profil et réserver une table. Les décisions, activités et relevés restent accessibles depuis le même espace.</p></div><div><a class="btn" href="/cercle-demo">Explorer l’interface de démonstration ↗</a><a href="/cercle-demo/" class="textlink">Explorer l’application ↗</a></div></section><p class="smallnote">Les cartes publiques sont la communication de présentation du projet. Aucun message n’est envoyé vers Instagram ou un autre réseau externe. Les visuels représentent un concept, pas des installations existantes.</p>`};
function terracePlan(){return `<svg viewBox="0 0 760 340" role="img" aria-label="Plan d’intention de la terrasse : cafétéria à gauche, jardin couvert et bancs au centre, tables de travail et rendez-vous à droite"><rect x="15" y="15" width="730" height="310" rx="20" fill="#e6ecdc" stroke="#a0b58b"/><path d="M35 35H725M35 305H725" stroke="#739065" stroke-width="15" stroke-dasharray="18 8"/><rect x="45" y="75" width="125" height="165" rx="10" fill="#b9916b"/><text x="108" y="140" text-anchor="middle" fill="#fff" font-size="16">CAFÉTÉRIA</text><text x="108" y="168" text-anchor="middle" fill="#fff" font-size="12">Comptoir café</text><rect x="215" y="65" width="175" height="30" rx="8" fill="#51715b"/><rect x="215" y="245" width="175" height="30" rx="8" fill="#51715b"/><text x="302" y="85" text-anchor="middle" fill="#fff" font-size="13">BANC FLEURI</text><circle cx="270" cy="170" r="33" fill="#64806a"/><circle cx="365" cy="170" r="33" fill="#64806a"/><text x="318" y="226" text-anchor="middle" fill="#36513d" font-size="13">JARDIN COUVERT</text><path d="M440 60V280" stroke="#b6c8a4" stroke-width="2" stroke-dasharray="6 5"/><rect x="480" y="70" width="90" height="55" rx="10" fill="#466b51"/><rect x="605" y="70" width="90" height="55" rx="10" fill="#466b51"/><text x="588" y="155" text-anchor="middle" fill="#36513d" font-size="14">2 PLACES COWORKING</text><rect x="510" y="195" width="155" height="60" rx="12" fill="#466b51"/><text x="588" y="230" text-anchor="middle" fill="#fff" font-size="14">RENDEZ-VOUS</text><text x="588" y="280" text-anchor="middle" fill="#36513d" font-size="12">Une table · 2 à 4 personnes</text></svg>`}
views.terrasse=function(){return `<section class="terrace-hero"><img src="assets/terrasse-fleurie.webp" alt="Terrasse résidentielle couverte : pergola verte fleurie, tables et chaises en métal, bancs, cafétéria et entrepreneurs"><div><div class="eyebrow">LE NOUVEAU CŒUR COMMUN DU DOMAINE</div><h1>La Serre du Domaine.</h1><p>Un café sous les fleurs.<br>Une rencontre qui fait avancer les projets.</p><a class="btn" href="/cercle-demo">Imaginer ma prochaine rencontre ↗</a></div><small>VISUEL CONCEPTUEL · IMAGE ILLUSTRATIVE</small></section><div class="terrace-intro"><div><div class="eyebrow">SE RENCONTRER · TRAVAILLER · PARTAGER</div><h2>Votre terrasse résidentielle,<br>ouverte sur la vie commune.</h2></div><p>Une couverture légère sous une pergola verte, des plantes grimpantes et des fleurs abondantes. Des tables en métal au dessin contemporain, des chaises et des bancs invitent à s’installer.</p></div><div class="terrace-usages">${[['01','La cafétéria','Un comptoir café, des pauses et des tables pour se retrouver. La carte et les horaires seront définis avec le projet.'],['02','Le jardin couvert','Un espace de détente fleuri, des bancs et une circulation centrale entre les plantations.'],['03','Le coin entrepreneurs','Deux places de coworking et une table de rendez-vous pour 2 à 4 personnes, avec planning de réservation privé.']].map(x=>`<article><small>${x[0]}</small><h3>${x[1]}</h3><p>${x[2]}</p></article>`).join('')}</div><section class="terrace-plan"><div><div class="eyebrow">COMPRENDRE LES USAGES</div><h2>À chacun sa place.<br>Un lieu en commun.</h2><p>Le plan distingue les pauses conviviales et les espaces de travail. Les réservations évitent qu’une réunion et une séance de travail se disputent la même table.</p><a class="btn light" href="#ville" onclick="citySelected='commun'">Situer la terrasse en 3D ↗</a></div>${terracePlan()}</section><section class="terrace-book"><div><div class="eyebrow">LE PLANNING DANS LE CERCLE</div><h2>Un rendez-vous ou une matinée de travail ?</h2><p>Choisissez une date, une table et un créneau de deux heures. Dans l’espace privé, les disponibilités sont partagées entre riverains et contrôlées pour éviter les doubles réservations.</p><p class="smallnote">Lieu en projet : les réservations expriment une intention d’usage. Mobilier, couverture, confort acoustique et implantation restent à dimensionner.</p></div><div><a class="btn" href="/cercle-demo/">Réserver dans mon espace riverain ↗</a><a class="btn light" href="/cercle-demo">Tester le planning en démonstration ↗</a><button class="textlink" onclick="shareTerrace()">Copier le lien de présentation ↗</button></div></section>`};
routes.push(['terrasse','❀','La Serre · Terrasse & café']);
const communal=cityPlaces.find(p=>p.id==='commun');Object.assign(communal,{name:'La Serre du Domaine',short:'Terrasse · café & travail',label:'LA SERRE · TERRASSE',desc:'Une terrasse résidentielle sous une pergola verte très fleurie : cafétéria, tables en métal, chaises, bancs et coin entrepreneurs.',stat:'3',unit:'usages : café, détente, travail',stat2:'3',unit2:'tables de travail à réserver',detail:'Deux places de coworking et une table rendez-vous. Maquette d’intention : couverture, plantes et mobilier représentés en volumes simplifiés.',action:'Découvrir la terrasse',route:'terrasse'});
const actionBeforeTerrace=cityAction;cityAction=function(id){if(id==='commun'){location.hash='#terrasse';return}actionBeforeTerrace(id)};
const cityDetailBeforeTerrace=cityDetailHTML;cityDetailHTML=function(){return (citySelected==='commun'?'<img class="city-terrace-photo" src="assets/terrasse-fleurie.webp" alt="Concept de La Serre, terrasse verte et fleurie">':'')+cityDetailBeforeTerrace()};
const homeBeforeTerrace=views.accueil;views.accueil=function(){return homeBeforeTerrace().replace('<section class="projection-choice">',`<section class="home-terrace"><img src="assets/terrasse-fleurie.webp" alt="Terrasse commune fleurie avec cafétéria et espace de travail" loading="lazy"><div><div class="eyebrow">LA SERRE · LE NOUVEAU LIEU COMMUN</div><h2>Un café, une rencontre.<br>Et des projets qui grandissent.</h2><p>Une terrasse verte couverte, des tables en métal, des bancs fleuris et une place pour entreprendre ensemble.</p><a class="btn light" href="#terrasse">Entrer dans La Serre ↗</a></div></section><section class="projection-choice">`)};
projectionDays[3]={...projectionDays[3],image:'terrasse-fleurie.webp',title:'Se retrouver sous les fleurs.',text:'Un café à La Serre, un rendez-vous entre entrepreneurs ou une rencontre entre voisins. Réservez une table dans le Cercle et prolongez les échanges dans votre espace privé.',link:'#terrasse',action:'Découvrir La Serre'};
const gateBeforeTerrace=views.riverains;views.riverains=views.resident=function(){return gateBeforeTerrace()+`<section class="journal-private"><div><h2>Découvrez le nouveau réseau riverain.</h2><p>Fil visuel, profils, commentaires, favoris et réservations de tables. Testez l’interface avec des exemples identifiés.</p></div><a class="btn light" href="/cercle-demo">Explorer l’aperçu ↗</a></section>`};
render();
